int main(int argc,char**argv){
 ios::sync_with_stdio(false);cin.tie(nullptr);
 Game g;g.init(1,argv);
 g.bankMode=5;
 int forced=-1;
 for(int i=1;i<argc;i++){
  constexpr string_view p="--terry-force-map=";
  string_view v(argv[i]);
  if(v.starts_with(p))forced=clamp(atoi(argv[i]+p.size()),0,4);
 }
 g.terryLayout(forced);
 if(forced>=0)cerr<<"terry_forced_map="<<g.terryMap<<'\n';
 g.setupObservedMotion();
 int stopTurn=-1;
 bool changed=false;
 for(;g.turn<300;g.turn++){
  if(stopTurn<0&&changed&&g.globallyClear())stopTurn=g.turn;
  if(stopTurn>=0){
   g.act.assign(g.humans.size(),'.');
   if(g.turn==160)g.residual160=0;
  }else
   {
    auto proposal=g.bankMode?g.integratedBankPlan():g.plan();
    proposal=g.repair(std::move(proposal));
    if(!g.bankMode||g.integratedMode[g.turn]==4)
     proposal=g.terminal(g.tacticalGate(std::move(proposal)));
    g.act=std::move(proposal);
   }
  changed=g.act.find_first_of("udlr")!=string::npos;
  g.bankRecord();
  cout<<g.act<<'\n'<<flush;
  if(!g.advance())break;
 }
 if(const char* p=getenv("AHC008_TERRY_LOG")){
  ofstream f(p);
  f<<g.terryMap<<" "<<g.terryRotation<<" "<<terry_maps::weights::trained<<" "<<g.terryBuild.nominal<<" "
   <<g.terryBuild.issued<<" "<<g.terryBuild.skipped<<" "<<g.terryBuild.relayTurn<<" "<<g.terryBuild.relayCost<<" "
   <<g.terryForecasts<<" "<<g.lateResult.pairs<<" "<<g.lateResult.rail<<" "<<g.lateResult.cut<<" "
   <<g.lateResult.rail_wall_changed<<" "<<g.lateResult.cut_wall_changed<<" "<<g.terryCutChosen<<" "<<g.terryCut.closes<<'\n';
  for(int t:g.terryBuild.relayArrival)f<<t<<" ";
  f<<'\n';
 }
 if(const char* p=getenv("AHC008_ARTICLE_LOG")){
  ofstream f(p);
  for(int t=0;t<300;t++)if(g.integratedMode[t]||g.integratedReady[t]||g.integratedLocks[t])
   f<<t<<" "<<g.integratedMode[t]<<" "<<g.integratedReady[t]<<" "<<g.integratedLocks[t]<<'\n';
 }
 if(const char* p=getenv("AHC008_BRIDGE_LOG")){
  ofstream f(p);
  for(const auto& e:g.bridgeReport)f<<e.turn<<" "<<e.kind<<" "<<e.worker<<" "<<e.tube<<" "<<e.from
     <<" "<<e.to<<" "<<e.supply<<'\n';
 }
 if(const char* p=getenv("AHC008_GLOBAL_CLEAR_LOG")){
  ofstream f(p);f<<stopTurn<<'\n';
 }
 if(const char *p=getenv("AHC008_SEAM_MEMO_LOG")){
  ofstream f(p);f<<g.memoQueries<<" "<<g.memoHits<<" "<<g.seamParts.capacity()<<"\n";
 }
 if(const char *p=getenv("AHC008_RESCUE_LOG")){
  ofstream f(p);f<<g.residual160<<" "<<g.bankRelease<<"\n";
 }
#ifdef GATE_DIAG
 cerr<<"gate "<<g.gateSearch<<" "<<g.gatePrep<<" "<<g.gateApplied<<"\n";
#endif
#ifdef HAB_DIAG
 array<int,6> active{}; g.workers[0].bfs.run(g.humans[0],[&](int p){return !g.wall[p];});
 int a=0;for(int p=0;p<V;p++)a+=g.workers[0].bfs.distance(p)>=0;
 for(auto pp:g.pets)if(g.workers[0].bfs.distance(pp.p)>=0)active[pp.t]++;
 cerr<<"diag "<<a;for(int i=1;i<=5;i++)cerr<<" "<<active[i]; cerr<<"\n";
#endif
}
